#' Outcome Organizer (Python Core)
#'
#' 
#' @param data .
#' @param outcome .
#' @param outcomeLevel .
#' @param analysistype .
#' @param multievent .
#' @param dod .
#' @param dooc .
#' @param awd .
#' @param awod .
#' @param diagnostics .
#' @param visualization .
#' @param showNaturalSummary .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mapping} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$frequencies} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$preview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$report} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$distribution} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$addOutcome} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyoutcomeorganizer <- function(
    data,
    outcome = NULL,
    outcomeLevel,
    analysistype = "os",
    multievent = FALSE,
    dod,
    dooc,
    awd,
    awod,
    diagnostics = FALSE,
    visualization = FALSE,
    showNaturalSummary = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyoutcomeorganizer requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL))


    options <- pyoutcomeorganizerOptions$new(
        outcome = outcome,
        outcomeLevel = outcomeLevel,
        analysistype = analysistype,
        multievent = multievent,
        dod = dod,
        dooc = dooc,
        awd = awd,
        awod = awod,
        diagnostics = diagnostics,
        visualization = visualization,
        showNaturalSummary = showNaturalSummary,
        showConsole = showConsole)

    analysis <- pyoutcomeorganizerClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

